<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>The Louisiana Architect - Page 8</title>
    <style>
        * {
            box-sizing: border-box;
        }
        body {
            font-family: "Times New Roman", Times, serif;
            font-size: 14.5px;
            line-height: 1.25;
            color: #1a1a1a;
            background-color: #fdfdfd;
            margin: 0;
            padding: 40px 50px;
        }
        .page-container {
            max-width: 950px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
        }
        .main-columns {
            display: grid;
